<?php if (!defined('__TYPECHO_ROOT_DIR__')) exit; ?>
<section class="comments panel" id="comments"><h3>▣ 评论告示牌</h3><?php $this->comments()->to($comments); ?><?php if($comments->have()): ?><?php $comments->listComments(array('dateFormat' => 'Y/m/d \a\t H:i')); ?><?php endif; ?>
<?php if($this->allow('comment')): ?><div id="<?php $this->respondId(); ?>" class="respond"><h3>留下你的评论</h3><form method="post" action="<?php $this->commentUrl(); ?>" id="comment-form"><p><label for="author">昵称</label><input id="author" name="author" value="<?php $this->remember('author'); ?>" required></p><p><label for="mail">邮箱</label><input id="mail" type="email" name="mail" value="<?php $this->remember('mail'); ?>" required></p><p><label for="url">网站（可选）</label><input id="url" type="url" name="url" value="<?php $this->remember('url'); ?>"></p><p><label for="textarea">留言</label><textarea id="textarea" name="text" rows="5" required><?php $this->remember('text'); ?></textarea></p><button type="submit">发送留言 ▶</button></form></div><?php endif; ?></section>
